syntax:
type **ptr; // pointer to pointer
*ptr; // dereferencing pointer to pointer
ptr + offset; // pointer arithmetic with multi-level pointers
(char *)ptr; // casting pointers for type reinterpretation

// Example of complex pointer usage
int ***pptr; // triple pointer
int **dptr; // double pointer
int *iptr; // single pointer

// Assignments
iptr = &some_int;
dptr = &iptr;
pptr = &dptr;
